    try { localStorage.setItem(WIN_IMG_KEY, cv.toDataURL("image/jpeg", .85)); toast("Eigenes Sieger-Bild gespeichert (nur in diesem Browser)"); }
    catch { toast("Bild konnte nicht gespeichert werden"); }
