    chest: `<rect x="40" y="120" width="160" height="96" rx="10" fill="#7a4a1e" stroke="${a}" stroke-width="6"/><path d="M40 130 C40 70 200 70 200 130" fill="#9a5f28" stroke="${a}" stroke-width="6"/><rect x="108" y="138" width="24" height="30" rx="4" fill="#ffd23f"/><path d="M60 110 L40 70 M120 92 V40 M180 110 L200 70" stroke="#ffd23f" stroke-width="5" stroke-linecap="round"/>`,
