/* ---------- Vergleich ---------- */
function compare(col, gv, tv, target) {
  const base = s => String(s).replace(/\s*\(.*\)$/, "").replace(/^Ehem\.\s*/, "");
  switch (col.t) {
    case "eq": case "num": case "ord": return gv === tv ? "ok" : "bad";
    case "set": case "setbase": {
      const a = list(gv), b = list(tv);
      if (a.length === b.length && a.every(x => b.includes(x))) return "ok";
      if (a.some(x => b.includes(x))) return "part";
      if (col.t === "setbase" && a.some(x => b.map(base).includes(base(x)))) return "part";
      return "bad";
    }
    case "slot": return gv === tv ? "ok" : (gv !== "Keiner" && gv === target[col.other] ? "part" : "bad");
    case "grp": return gv === tv ? "ok" : (col.part && col.part(gv) && col.part(gv) === col.part(tv) ? "part" : "bad");
    case "fruit": return gv === tv ? "ok" : (/Zoan/.test(gv) && /Zoan/.test(tv) ? "part" : "bad");
  }
}
const DIFF = () => store.diff || "normal";
const arrow = (col, gv, tv) => DIFF() !== "hard" && (col.t === "num" || col.t === "ord") && gv !== tv ? (tv > gv ? "▲" : "▼") : "";
const hintAfter = h => Math.max(h.min || 0, DIFF() === "easy" ? Math.max(2, h.after - 2) : DIFF() === "hard" ? h.after + 3 : h.after);
const show = (col, v, c) => col.show ? col.show(v, c) : (Array.isArray(v) ? (v.length ? v.join(", ") : "Keine") : v);
const emoji = r => ({ ok: "✅", part: "🟡", bad: "❌" })[r];   // N1: Form statt nur Farbe (Haken / Kreis / Kreuz) – auch für Farbenblinde lesbar

const gensFor = g => g.gens ? (store.gens && store.gens.length ? store.gens : ALL_GENS) : ALL_GENS;
const dayKey = (g, m) => `${g.id}:${m.id}:${g.gens ? genKey(gensFor(g)) : "-"}:${today}`;
function state() {
  const gens = duel ? duel.gens : gensFor(game);
  if (play === "race" && race) return { target: race.target, guesses: race.guesses, won: race.won, gens: race.gens || ALL_GENS, kind: "race" };
  if (play === "endless") return { target: endless.target, guesses: endless.guesses, won: endless.won, gaveup: endless.gaveup, gens, kind: "endless" };
  if (play === "duel" && duel) {
    const s = store.duels[duel.code] || (store.duels[duel.code] = { guesses: [], won: false });
    return { target: duelTarget(game, kind, gens, duel.code), guesses: s.guesses, won: s.won, raw: s, gens, kind: "duel" };
  }
  if (play === "archiv" && archDay != null) {
    const ka = archKey(game, kind, archDay), sa = store.days[ka] || (store.days[ka] = { guesses: [], won: false });
    return { target: dailyTarget(game, kind, gens, archDay), guesses: sa.guesses, won: sa.won || !!sa.gaveup, gaveup: !!sa.gaveup && !sa.won, raw: sa, gens, kind: "archiv" };
  }
  const k = dayKey(game, kind);
  const s = store.days[k] || (store.days[k] = { guesses: [], won: false });
  return { target: dailyTarget(game, kind, gens, day), guesses: s.guesses, won: s.won || !!s.gaveup, gaveup: !!s.gaveup && !s.won, raw: s, gens, kind: "daily" };
}
const solved = (g, m) => { const s = store.days[dayKey(g, m)]; return !!(s && s.won); };
let archDay = null;
const dateOfDay = d => new Date(Date.UTC(2026, 0, 1) + d * 864e5).toISOString().slice(0, 10);
const archKey = (g, m, d) => `${g.id}:${m.id}:${g.gens ? genKey(gensFor(g)) : "-"}:${dateOfDay(d)}`;
const dm = d => { const x = dateOfDay(d); return x.slice(8, 10) + "." + x.slice(5, 7) + "."; };
function recordWin(g, m, tries) {
  const k = g.id + ":" + m.id, s = store.stats[k] || (store.stats[k] = { wins: 0, streak: 0, best: 0, last: null, tries: 0 });
  if (s.last === today) return;
  const y = dateStr(new Date(Date.UTC(+today.slice(0, 4), +today.slice(5, 7) - 1, +today.slice(8, 10), 12) - 864e5));
  s.streak = s.last === y ? s.streak + 1 : 1; s.best = Math.max(s.best, s.streak); s.wins++; s.tries += tries; s.last = today;
  const b = tries >= 10 ? "10+" : String(tries); s.dist = s.dist || {}; s.dist[b] = (s.dist[b] || 0) + 1;
}
function startEndless() { const p = pool(game, kind, gensFor(game)); endless = { target: p[Math.floor(Math.random() * p.length)], guesses: [], won: false }; }

