  if (new Set(names).size !== names.length) { toast("Bitte unterschiedliche Namen verwenden"); return; }
  const st = { i: newId(), s: newId() + newId(), m, n: names, v: qv.avs.slice(0, np), c: Array(QZ_R).fill(null), a: Array(np).fill(""), online: m > 0 && !!qv.online, at: Date.now() };
