  const a = t.dataset.q, st = qCur();
  if (a === "home") { clearTimeout(qTimer); view = "quiz"; qv = { screen: "home" }; window.scrollTo({ top: 0 }); return render(false); }
  if (a === "vs") { qv = { screen: "vs" }; return render(false); }
  if (a === "setup") { qv = { screen: "setup", m: +t.dataset.m, online: false }; return render(false); }
  if (a === "where") { qv.online = t.dataset.w === "online"; return render(false); }
  if (a === "av") { qv.avs[+t.dataset.i] = randAv(); return render(false); }
