  if (a === "import") return qImport($("#qzcode").value);
  if (a === "open") return qOpen(t.dataset.id);
  if (a === "del") { delete QS().matches[t.dataset.id]; save(); return render(false); }
  if (a === "match") { qv.screen = "match"; return render(false); }
  if (a === "whoami") { qv.screen = "who"; return render(false); }
  if (a === "iam" && st) { QS().me[st.i] = +t.dataset.p; save(); qv.screen = "match"; return render(false); }
