document.addEventListener("input", e => { if (e.target.classList && e.target.classList.contains("qz-in") && e.target.dataset.i != null && qv.names) qv.names[+e.target.dataset.i] = e.target.value; });

/* ===================== Live-Räume: zusammen spielen nur über einen Link =====================
   Verbindung direkt zwischen den Browsern (WebRTC über Trystero/Nostr, kein Konto).
   Optional: ein eigener kleiner EU-Server (ONLINE_SERVER, siehe server/README.md) vermittelt Mitspieler (Schnelle Suche,
   offene Räume) und dient als Relay für die Verbindungsdaten; die Spieldaten laufen weiter direkt zwischen den Browsern.
   Der Ersteller des Raums ist der Host und gibt den Spielstand vor (Lobby, Live-Quiz, Live-Rennen, Arena).
   Fallback ohne Internet-Signalisierung: BroadcastChannel (mehrere Tabs am selben Gerät, auch für Tests). */
/* ===================== R67 D: zentrale tolerante Eingabe =====================
   normAns(s): Groß/Klein egal, Akzente/Umlaute egal (ä→a, é→e, ß→ss, æ→ae, ø→o …), Leerzeichen/Bindestriche/Punkte/Apostrophe egal.
   ansLoose(s): zusätzlich ae/oe/ue → a/o/u (damit „Mueller“ = „Müller“, „Grossbritannien“ = „Großbritannien“).
   matchAns(eingabe, kandidaten, namen?) → genau EIN Kandidat oder null. Stufen: exakt → locker → Alias (ANS_ALIAS) → ohne Artikel
   → ganzes Namenswort (≥ 4 Zeichen) → Tippfehler (Damerau-Levenshtein ≤ 1, erst ab 6 Zeichen). Treffen mehrere Kandidaten gleich gut → null (nie zwei Lösungen verwechseln). */
const ANS_SPECIAL = { "ß": "ss", "ẞ": "ss", "æ": "ae", "Æ": "ae", "œ": "oe", "Œ": "oe", "ø": "o", "Ø": "o", "đ": "d", "Đ": "d", "ł": "l", "Ł": "l", "ı": "i", "þ": "th", "Þ": "th", "ð": "d", "♀": "w", "♂": "m" };
