/* ===================== R67 D: Endlos-Statistik (eigene, zählt nicht für Serie/Tagesziel) ===================== */
const ENDL = id => { const E = store.endl || (store.endl = {}); return E[id] || (E[id] = { n: 0, w: 0, t: 0, pts: 0, s: 0, bs: 0, best: null }); };
function endRec(id, o) {
  const e = ENDL(id); e.n++;
  if (o.pts != null) { e.pts += o.pts; e.best = Math.max(e.best || 0, o.pts); const good = o.pts >= (o.max || 100) * .6; e.s = good ? e.s + 1 : 0; if (good) e.w++; }
  else if (o.won) { e.w++; e.t += o.tries || 0; e.s++; if (o.tries) e.best = e.best == null ? o.tries : Math.min(e.best, o.tries); }
  else e.s = 0;
  e.bs = Math.max(e.bs, e.s); save();
}
function endStatHtml(id, type) {
  const e = ENDL(id), it = (v, t) => `<span><b>${v}</b> ${t}</span>`;
  if (!e.n) return `<div class="endst" data-endst="${esc(id)}"><b>Endlos</b><span>Zählt nicht für Serie und Tagesziel – eigene Statistik.</span></div>`;
  const avg = type === "pts" ? it(Math.round(e.pts / e.n), "Ø Punkte") : type === "w" ? "" : e.w && e.t ? it((e.t / e.w).toFixed(1), "Ø Versuche") : "";
  return `<div class="endst" data-endst="${esc(id)}"><b>Endlos-Statistik</b>${it(e.n, "gespielt")}${it(e.w, type === "pts" ? "gut (≥ 60 %)" : type === "w" ? "gewonnen" : "gelöst")}${avg}${it(e.s, "in Folge")}${it(e.bs, "Rekord")}</div>`;
}
